# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: gather
def gather(xs, floor_=2):
    return [v for v in xs if v > floor_]

# region: emit
def emit(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: digest
def digest(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return digest(sift(emit(gather(intake(render(raw))))))

